def get_visualization_metrics():
    conn = _learning_conn()
    metrics = {}
    table_map = {
        "learning_articles": "learning_articles",
        "form_guides": "tax_form_guides",
        "tutorial_videos": "tutorial_videos",
        "workspaces": "workspaces",
        "workspace_notes": "workspace_notes",
        "discussion_threads": "discussion_threads",
        "discussion_messages": "discussion_messages",
        "execution_tasks": "execution_tasks",
        "document_templates": "document_templates",
        "generated_documents": "generated_documents",
    }

    for key, table_name in table_map.items():
        try:
            metrics[key] = conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0]
        except Exception:
            metrics[key] = 0

    conn.close()

    # pull from main app helpers where available
    try:
        metrics["trusts"] = len(get_all_trusts())
    except Exception:
        metrics["trusts"] = 0

    try:
        metrics["fiduciaries"] = len(get_all_fiduciaries())
    except Exception:
        metrics["fiduciaries"] = 0

    try:
        metrics["instruments"] = len(get_all_instruments())
    except Exception:
        metrics["instruments"] = 0

    try:
        metrics["media"] = len(get_all_media())
    except Exception:
        metrics["media"] = 0

    return metrics

def get_visualization_timeline():
    conn = _learning_conn()
    timeline = []

    sources = [
        ("Workspace", "workspaces", "workspace_id", "title"),
        ("Discussion Thread", "discussion_threads", "thread_id", "title"),
        ("Execution Task", "execution_tasks", "task_id", "title"),
        ("Generated Document", "generated_documents", "document_id", "title"),
        ("Tutorial Video", "tutorial_videos", "video_id", "title"),
    ]

    for label, table_name, id_col, title_col in sources:
        try:
            rows = conn.execute(
                f"SELECT {id_col} as item_id, {title_col} as item_title, created_at FROM {table_name} ORDER BY created_at DESC LIMIT 10"
            ).fetchall()
            for row in rows:
                timeline.append({
                    "kind": label,
                    "item_id": row["item_id"],
                    "item_title": row["item_title"],
                    "created_at": row["created_at"],
                })
        except Exception:
            continue

    conn.close()
    timeline.sort(key=lambda x: x.get("created_at") or "", reverse=True)
    return timeline[:30]

def build_system_health_report():
    required_tables = {
        "audit_log": ["id", "entity_type", "entity_id", "action", "note", "created_at", "previous_hash", "entry_hash", "hash_algorithm"],
        "permissions": ["permission_id", "permission_name", "description"],
        "role_permissions": ["id", "role_name", "permission_name"],
        "app_users": ["user_id", "username", "password_hash", "role_name", "status"],
        "user_permission_overrides": ["id", "username", "permission_name", "effect", "created_at"],
    }

    table_reports = []
    overall_ok = True

    for table_name, required_columns in required_tables.items():
        exists = table_exists(table_name)
        columns = get_table_columns(table_name) if exists else []
        missing_columns = [col for col in required_columns if col not in columns]

        ok = exists and not missing_columns
        if not ok:
            overall_ok = False

        table_reports.append({
            "table_name": table_name,
            "exists": exists,
            "columns": columns,
            "missing_columns": missing_columns,
            "ok": ok,
        })

    return {
        "overall_status": "OK" if overall_ok else "ATTENTION",
        "tables": table_reports,
    }

def run_safe_recovery_migrations():
    """
    Re-runs safe startup migration/initialization routines.
    This is intentionally non-destructive:
    - creates missing tables
    - adds missing columns where coded
    - seeds missing default permissions
    - does not delete user data
    """
    results = []

    try:
        init_audit_table()
        results.append({"name": "audit_log", "status": "OK", "note": "Audit table and hash columns verified."})
    except Exception as exc:
        results.append({"name": "audit_log", "status": "ERROR", "note": str(exc)})

    try:
        ensure_role_tables()
        results.append({"name": "permissions", "status": "OK", "note": "Permission matrix tables and defaults verified."})
    except Exception as exc:
        results.append({"name": "permissions", "status": "ERROR", "note": str(exc)})

    try:
        ensure_user_tables()
        results.append({"name": "app_users", "status": "OK", "note": "User table verified."})
    except Exception as exc:
        results.append({"name": "app_users", "status": "ERROR", "note": str(exc)})

    try:
        ensure_user_permission_override_tables()
        results.append({"name": "user_permission_overrides", "status": "OK", "note": "User override table verified."})
    except Exception as exc:
        results.append({"name": "user_permission_overrides", "status": "ERROR", "note": str(exc)})

    return {
        "overall_status": "OK" if all(item["status"] == "OK" for item in results) else "ATTENTION",
        "results": results,
    }
